insert into passages (title,body,"wordCount",difficulty,topic,status) values ('The Limits of Prediction', 'Predictions can help people prepare, but they can also create false confidence. Weather forecasts, economic models, and exam estimates are based on available information, not certainty. When conditions change, even a careful prediction may fail. The best use of prediction is therefore practical rather than absolute: it should guide decisions while leaving room for revision. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 76, 7, 'prediction', 'approved');
