insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'What problem does the passage mainly warn against in the passage titled Sleep and Memory for this sleep and memory passage in a central research briefing context?','Reading carefully before responding.','Using any evidence before making decisions.','Treating a useful idea as if it had no limits.','Changing an opinion when facts change.','C','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Public Trust in Science', 'Scientific knowledge changes as new evidence appears, and this can confuse the public. Some people interpret change as weakness, but revision is one of science’s strengths. A claim that can be tested and corrected is more reliable than one that never changes. Public trust depends on understanding that uncertainty and progress often exist together. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 75, 6, 'science', 'approved');
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Which question is the passage most likely trying to answer in the passage titled Public Trust in Science for this science passage in a online research briefing context?','Who invented science in ancient times?','Why should science be ignored completely?','Why is every alternative better than science?','How can science be useful without being treated as a perfect solution?','D','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'What is the main purpose of the passage in the passage titled Public Trust in Science for this science passage in a evening research briefing context?','To explain a balanced view of science.','To describe an unrelated historical event.','To advertise a product related to science.','To prove that science has no importance.','A','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'Which statement best reflects the author’s attitude toward science in the passage titled Public Trust in Science for this science passage?','It should replace all other approaches immediately.','It can be valuable, but only when its limits are understood.','It is completely useless in every situation.','It is too simple to deserve serious attention.','B','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'According to the passage, what is one risk connected with science in the passage titled Public Trust in Science for this science passage?','People will always become more accurate.','It removes every possible problem.','People may overlook an important limitation.','It prevents any kind of improvement.','C','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'C1',(select max(id) from passages),'approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel","passageId",status,"isPilot") values ('reading_comprehension',6,'What can be inferred from the passage in the passage titled Public Trust in Science for this science passage in a introductory research briefing context?','The author rejects all practical solutions.','The passage supports ignoring evidence.','The author believes simple choices are always wrong.','A careful approach is better than an automatic or extreme response.','D','התשובה נתמכת ברעיון המרכזי, בפרט מפורש או בהיסק סביר מתוך הקטע.','["simulation_28", "reading_comprehension", "practice_pool"]'::jsonb,80,'B2',(select max(id) from passages),'approved',false);
insert into passages (title,body,"wordCount",difficulty,topic,status) values ('The Role of Difficulty', 'Tasks that are too easy may feel pleasant, but they often produce little growth. Moderate difficulty forces learners to retrieve information, compare options, and notice gaps in understanding. This kind of challenge can be uncomfortable, yet it supports durable learning. The goal is not to make study painful, but to make it demanding enough to be useful. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 78, 6, 'difficulty', 'approved');
